def sort_age(lst):
    if lst == []:
        return []
    agelist = [lst[0],]
    for i in range(1,len(lst)):
        if lst[i][1] > agelist[0][1]:
            agelist.insert(0, lst[i])
        elif lst[i][1] < agelist[len(agelist)-1][1]:
            agelist.insert(len(agelist), lst[i])
        else:
            for x in range(0,len(agelist)):
                if agelist[x][1]> lst[i][1] > agelist[x+1][1]:
                    agelist.insert(x+1, lst[i])
                    break
    return agelist

def sort_age(lst):
    if len(lst)<=1:
        return lst
    else:
        used_lst=lst.copy()
        ages=()
        for i in lst:
            ages+=(i[1],)
        for i in lst:
            if i[1]==max(ages):
                new_lst=[i]
                used_lst.remove(i)
        return new_lst+sort_age(used_lst)

def sort_age(lst):
    if lst == []:
        return []
    agelist = [lst[0]]
    for i in lst[1:]:
        if i[1] > agelist[0][1]:
            agelist.insert(0, i)
        elif i[1] < agelist[-1][1]:
            agelist.append(i)
        else:
            for x in range(len(agelist) - 1):
                if i[1] < agelist[x][1] and i[1] > agelist[x+1][1]:
                    agelist.insert(x+1, i)
    return agelist

def merge(one,two):
    new_tup = []
    while one and two:
        if one[0][1] < two[0][1]:
            new_tup.append(two.pop(0))
        else:
            new_tup.append(one.pop(0))
    new_tup.extend(one)
    new_tup.extend(two)
    return new_tup

def sort_age(lst):
    n = len(lst)
    if n <2:
        return lst
    left = sort_age(lst[:n//2])
    right = sort_age(lst[n//2:])
    return merge(left,right)

