    newlst=[]
    while lst:
        maximum = lst[0]
        for i in lst:
            if i[1] >= maximum[1]:
                maximum = i
        lst.remove(maximum)
        newlst.append(maximum)
    return newlst

def sort_age(lst):
    # Fill in your code here
    newlst=[]
    while lst:
        maximum = lst[0][1]
        i = lst[0]
        for j in lst:
            if j[1] > maximum:
                maximum = j[1]
                i = j
        lst.remove(i)
        newlst.append(i)
    return newlst

def sort_age(lst):
    # Fill in your code here
    newlst = []
    while lst:
        maximum = lst[0][1]
        for i in lst:
            if i[1] > maximum:
                maximum = i[1]
        for i in lst[:]:
            if i[1] == maximum:
                newlst.append(i)
                lst.remove(i)

    return newlst
